// Package transport provides predefined transport protocol.
package transport

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0

	TTHeader Protocol = 1 << iota // 1
	Framed                        // 2
	HTTP                          // 4
	GRPC                          // 8
	HESSIAN2                      // 16
	STREAMING                     // 32

	TTHeaderFramed      = TTHeader | Framed     // 3
	TTHeaderStreaming   = 64                    // dedicated flag
	GRPCStreaming       = 128                   // dedicated flag
	DefaultTransport    = Framed                // default transport
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
// Single flags return their name; composite flags return pipe-separated names.
func (tp Protocol) String() string {
	// Handle exact matches for known single and composite protocols
	switch tp {
	case PurePayload:
		return "PurePayload"
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case STREAMING:
		return "STREAMING"
	case TTHeaderFramed:
		return "TTHeaderFramed"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	}

	// Handle composite flags by building pipe-separated string
	var parts []string
	flags := []struct {
		flag Protocol
		name string
	}{
		{TTHeader, "TTHeader"},
		{Framed, "Framed"},
		{HTTP, "HTTP"},
		{GRPC, "GRPC"},
		{HESSIAN2, "Hessian2"},
		{STREAMING, "STREAMING"},
	}

	for _, f := range flags {
		if tp&f.flag != 0 {
			parts = append(parts, f.name)
		}
	}

	if len(parts) > 0 {
		result := parts[0]
		for i := 1; i < len(parts); i++ {
			result += "|" + parts[i]
		}
		return result
	}

	return Unknown
}
